from pyspark.sql import SparkSessionspark = SparkSession.builder \    .appName("ReadS3Parquet") \    .master("local[*]") \    .config(    "spark.jars.packages",    "org.apache.hadoop:hadoop-aws:3.5.0") \    .config(    "spark.hadoop.fs.s3a.aws.credentials.provider",    "software.amazon.awssdk.auth.credentials.ProfileCredentialsProvider") \    .getOrCreate()path = "s3a://garnetdurai-ecommerce-data-pipeline/ecommerce/processed_v2/"df = spark.read.parquet(path)df.printSchema()df.show(10, truncate=False)spark.stop()